mapper.update:
UPDATE lunaerp_production_yarn_requisition_item
SET deleted = 0,
    updater = #{updater},
    update_time = #{updateTime}
WHERE requisition_id IN (
    SELECT id FROM lunaerp_production_yarn_requisition
    WHERE weaving_order_id = #{weavingOrderId}
      AND tenant_id = #{tenantId}
)
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_production_yarn_requisition_item
WHERE requisition_id IN (
    SELECT id FROM lunaerp_production_yarn_requisition
    WHERE weaving_order_id = #{weavingOrderId}
      AND tenant_id = #{tenantId}
)
  AND deleted = 1
  AND tenant_id = #{tenantId}
